// MIT. Commercial scenarios over a saved SF97 review and its original analyzer.
import { createHash } from 'node:crypto';
import { analyze, merchantTerms } from '../analyze.mjs';

export const SCENARIO_REVIEW_SCHEMA = 'stellar-forge.merchant-scenario-review.v1';
const MICRO = 1_000_000n;
const MAX_TARGET = BigInt(Number.MAX_SAFE_INTEGER);
const own = (value, key) => Object.hasOwn(value, key);
const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const clone = value => structuredClone(value);
const canonical = value => JSON.stringify(value, (_, item) => object(item)
  ? Object.fromEntries(Object.keys(item).sort().map(key => [key, item[key]])) : item);
const digest = value => createHash('sha256').update(value).digest('hex');
const fingerprint = value => digest(canonical(value));
const fail = (code, message) => Object.assign(new TypeError(message), {code, status:422});
const routeFields = ['unitPriceUsd','priceBasis','perFulfilledUsd','perChallengeUsd','monthlyPaidTarget'];

function record(value, label) {
  if (!object(value)) throw fail('SCENARIO_INPUT_INVALID', `${label} must be an object.`);
  return value;
}

function allowed(value, fields, label) {
  record(value, label);
  const invalid = Object.keys(value).find(key => !fields.includes(key));
  if (invalid) throw fail('SCENARIO_INPUT_INVALID', `${label} has an unsupported field: ${invalid}.`);
}

// The original analyzer validates merchant inputs. These exact conversions are
// for its returned decimal values and the additional planning equations only.
function money(value, label = 'USD amount') {
  if (value === null) return null;
  if (typeof value !== 'string' || !/^-?(0|[1-9]\d*)(\.\d{1,6})?$/.test(value))
    throw fail('SCENARIO_AMOUNT_INVALID', `${label} must be a decimal string with at most six places.`);
  const negative = value.startsWith('-'), unsigned = negative ? value.slice(1) : value;
  const [whole, fraction = ''] = unsigned.split('.');
  const result = BigInt(whole) * MICRO + BigInt(fraction.padEnd(6, '0'));
  return negative ? -result : result;
}

function decimal(value, places) {
  if (value === null) return null;
  const unit = 10n ** BigInt(places), negative = value < 0n, absolute = negative ? -value : value;
  const fraction = String(absolute % unit).padStart(places, '0').replace(/0+$/, '');
  return `${negative ? '-' : ''}${absolute / unit}${fraction ? '.' + fraction : ''}`;
}

const usd = value => decimal(value, 6);
const ceil = (numerator, denominator) => numerator <= 0n ? 0n : (numerator + denominator - 1n) / denominator;
const max = (left, right) => left > right ? left : right;
const percent = (numerator, denominator) => numerator === null || denominator === 0n
  ? null : decimal(numerator * MICRO / denominator, 4);
const difference = (left, right) => left === null || right === null ? null : usd(money(left) - money(right));

function gcd(left, right) {
  while (right) [left, right] = [right, left % right];
  return left;
}

function marginInput(value) {
  if (typeof value !== 'string' || !/^(0|[1-9]\d?)(\.\d{1,4})?$/.test(value))
    throw fail('SCENARIO_MARGIN_INVALID', 'Target margin must be a decimal string from 0 to less than 100, with at most four places.');
  const [whole, fraction = ''] = value.split('.');
  return BigInt(whole) * 10_000n + BigInt(fraction.padEnd(4, '0'));
}

function goalInput(value) {
  if (value === undefined) return null;
  allowed(value, ['monthlyContributionUsd','marginPct'], 'scenario goal');
  const result = {};
  if (own(value, 'monthlyContributionUsd')) {
    if (typeof value.monthlyContributionUsd !== 'string' || !/^(0|[1-9]\d*)(\.\d{1,6})?$/.test(value.monthlyContributionUsd))
      throw fail('SCENARIO_GOAL_INVALID', 'Monthly contribution target must be a nonnegative USD string with at most six places.');
    result.monthlyContributionUsd = usd(money(value.monthlyContributionUsd));
  }
  if (own(value, 'marginPct')) result.marginPct = decimal(marginInput(value.marginPct), 4);
  return Object.keys(result).length ? result : null;
}

function commercial(terms) {
  return {merchantName:terms.merchantName, sharedMonthlyFixedUsd:terms.sharedMonthlyFixedUsd,
    routes:Object.fromEntries(Object.entries(terms.routes).map(([id, term]) => [id,
      Object.fromEntries(routeFields.map(field => [field, clone(term[field])]))]))};
}

function assumptionBasis(label, original) {
  return `Planning assumption (${label}); original basis: ${original}`.slice(0, 300);
}

function scenarioInput(value, index, sourceCommercial, selectedRoutes) {
  allowed(value, ['id','label','sharedMonthlyFixedUsd','routes','goal'], `scenario ${index + 1}`);
  if (typeof value.id !== 'string' || !/^[A-Za-z0-9][A-Za-z0-9_-]{0,63}$/.test(value.id) || value.id === 'baseline')
    throw fail('SCENARIO_ID_INVALID', 'Use a unique scenario ID of 1–64 letters, digits, underscores or hyphens; baseline is reserved.');
  if (typeof value.label !== 'string' || !value.label.trim() || value.label.length > 120)
    throw fail('SCENARIO_LABEL_INVALID', 'Give each scenario a label of 1–120 characters.');
  const input = {id:value.id, label:value.label.trim(), routes:{}};
  if (own(value, 'sharedMonthlyFixedUsd')) input.sharedMonthlyFixedUsd = value.sharedMonthlyFixedUsd;
  const patches = value.routes === undefined ? {} : record(value.routes, 'scenario routes');
  input.routes = Object.fromEntries(Object.entries(patches).map(([id, patch]) => {
    if (!own(sourceCommercial.routes, id)) throw fail('SCENARIO_ROUTE_UNKNOWN', `The saved seller has no route ${id}.`);
    if (!selectedRoutes.has(id)) throw fail('SCENARIO_ROUTE_OUTSIDE_REVIEW', `Route ${id} is outside this saved review's selected route scope.`);
    allowed(patch, routeFields, `scenario route ${id}`);
    const next = clone(patch);
    if (own(next, 'unitPriceUsd') && next.unitPriceUsd !== sourceCommercial.routes[id].unitPriceUsd && !own(next, 'priceBasis'))
      next.priceBasis = assumptionBasis(input.label, sourceCommercial.routes[id].priceBasis);
    return [id, next];
  }));
  const goal = goalInput(value.goal);
  if (goal) input.goal = goal;
  return input;
}

function applyInput(sourceCommercial, input) {
  const next = clone(sourceCommercial);
  if (own(input, 'sharedMonthlyFixedUsd')) next.sharedMonthlyFixedUsd = input.sharedMonthlyFixedUsd;
  for (const [id, patch] of Object.entries(input.routes)) next.routes[id] = {...next.routes[id], ...patch};
  return next;
}

function metrics(report) {
  const overview = report.overview, gross = money(overview.plannedMonthlyTargetGrossUsd);
  const variable = money(overview.plannedMonthlyTargetVariableCostsUsd);
  const after = money(overview.plannedMonthlyTargetContributionAfterFixedUsd);
  const before = variable === null ? null : gross - variable;
  const unknownInputs = [];
  if (overview.sharedMonthlyFixedUsd === null) unknownInputs.push('sharedMonthlyFixedUsd');
  const routes = report.routes.map(row => {
    const quote = money(row.quoteUsd), cost = money(row.variablePerFulfilledUsd);
    if (cost === null) unknownInputs.push(`routes.${row.routeId}.perFulfilledUsd`);
    const contribution = cost === null ? null : quote - cost;
    return {routeId:row.routeId, method:row.method, path:row.path, paidTargetMonth:row.paidTargetMonth,
      quoteUsd:row.quoteUsd, perFulfilledUsd:row.variablePerFulfilledUsd,
      unitContributionUsd:usd(contribution), unitMarginPct:percent(contribution, quote),
      breakEvenUnitPriceUsd:usd(cost), plannedGrossUsd:row.plannedMonthlyTargetGrossUsd,
      plannedContributionBeforeFixedUsd:row.plannedMonthlyTargetContributionBeforeFixedUsd};
  });
  return {scope:overview.sharedFixedCostApplied === false ? 'SELECTED_CURRENT_ROUTE' : 'CURRENT_SELLER',
    plannedPaidRequests:routes.reduce((sum, row) => sum + BigInt(row.paidTargetMonth), 0n).toString(),
    grossUsd:usd(gross), variableCostsUsd:usd(variable), contributionBeforeFixedUsd:usd(before),
    sharedFixedUsd:overview.sharedMonthlyFixedUsd, contributionAfterFixedUsd:usd(after),
    marginBeforeFixedPct:percent(before, gross), marginAfterFixedPct:percent(after, gross), unknownInputs, routes};
}

function attainment(value, goal) {
  const net = money(value.contributionAfterFixedUsd), gross = money(value.grossUsd);
  const contributionTargetMet = goal?.monthlyContributionUsd === undefined ? null
    : net === null ? null : net >= money(goal.monthlyContributionUsd);
  const marginTargetMet = goal?.marginPct === undefined ? null
    : net === null || gross === 0n ? null : net * MICRO >= gross * marginInput(goal.marginPct);
  const checks = [contributionTargetMet, marginTargetMet].filter(item => item !== null);
  const expected = goal ? Object.keys(goal).length : 0;
  return {monthlyContributionUsd:value.contributionAfterFixedUsd, marginPct:value.marginAfterFixedPct,
    contributionTargetMet, marginTargetMet,
    targetMet:!expected ? null : checks.includes(false) ? false : checks.length === expected ? true : null};
}

function scopeReason(value) {
  if (value.scope !== 'CURRENT_SELLER') return {reason:'Shared monthly fixed cost has no allocation in this route-filtered review.',
    requiredInputs:['wholeSellerReview']};
  if (value.unknownInputs.length) return {reason:'Enter the unknown fulfillment and shared fixed costs to calculate this whole-seller goal.',
    requiredInputs:value.unknownInputs};
  return null;
}

function scenarioProvenance(provenance, terms) {
  return {...clone(provenance), terms:digest(JSON.stringify(terms, null, 2) + '\n'),
    ...(typeof provenance.terms === 'string' ? {planningSourceTerms:provenance.terms} : {})};
}

function evaluate(context, inputs) {
  const terms = merchantTerms(context.seller, inputs);
  const report = analyze(context.seller, context.observation, terms, scenarioProvenance(context.provenance, terms));
  report.generatedAt = context.generatedAt;
  return {commercial:commercial(terms), terms, overview:report.overview, metrics:metrics(report), report};
}

function suggestion(context, current, goal, kind) {
  const byPrice = kind.endsWith('_PRICE'), isBreakEven = kind.startsWith('BREAK_EVEN');
  const label = `${isBreakEven ? 'Break even' : 'Reach target'} by ${byPrice ? 'unit price' : 'planned volume'}`;
  const base = {kind, label, status:'UNAVAILABLE'};
  const blocked = scopeReason(current.metrics);
  if (blocked) return {...base, ...blocked};
  const totalCost = money(current.metrics.variableCostsUsd) + money(current.metrics.sharedFixedUsd);
  const netTarget = goal.monthlyContributionUsd === undefined ? 0n : money(goal.monthlyContributionUsd);
  const margin = goal.marginPct === undefined ? null : marginInput(goal.marginPct);
  const proposed = clone(current.commercial), details = {};

  if (byPrice) {
    const volume = BigInt(current.metrics.plannedPaidRequests);
    if (!volume) return {...base, reason:'Enter a positive monthly paid target to solve a unit price at that volume.',
      requiredInputs:['routes.monthlyPaidTarget']};
    let requiredGross = totalCost + netTarget;
    if (margin !== null) requiredGross = max(requiredGross, max(1n, ceil(totalCost * MICRO, MICRO - margin)));
    const currentGross = money(current.metrics.grossUsd);
    const uplift = ceil(requiredGross - currentGross, volume);
    details.priceUpliftUsd = usd(uplift);
    details.requiredGrossUsd = usd(requiredGross);
    details.method = 'COMMON_MICRO_USD_UPLIFT_AT_SELECTED_TARGETS';
    for (const route of current.metrics.routes) {
      if (!BigInt(route.paidTargetMonth) || !uplift) continue;
      proposed.routes[route.routeId].unitPriceUsd = usd(money(route.quoteUsd) + uplift);
      proposed.routes[route.routeId].priceBasis = assumptionBasis(label, proposed.routes[route.routeId].priceBasis);
    }
  } else {
    const active = current.metrics.routes.filter(row => BigInt(row.paidTargetMonth) > 0n);
    if (!active.length) return {...base, reason:'Enter a positive monthly paid target to define the route mix.',
      requiredInputs:['routes.monthlyPaidTarget']};
    const divisor = active.reduce((value, row) => gcd(value, BigInt(row.paidTargetMonth)), 0n);
    const basket = active.map(row => ({routeId:row.routeId, requests:BigInt(row.paidTargetMonth) / divisor,
      quote:money(row.quoteUsd), cost:money(row.perFulfilledUsd)}));
    const basketGross = basket.reduce((sum, row) => sum + row.requests * row.quote, 0n);
    const basketVariable = basket.reduce((sum, row) => sum + row.requests * row.cost, 0n);
    const basketContribution = basketGross - basketVariable, fixed = money(current.metrics.sharedFixedUsd);
    details.currentBaskets = divisor.toString();
    details.basketGrossUsd = usd(basketGross);
    details.basketContributionUsd = usd(basketContribution);
    details.method = 'SMALLEST_INTEGER_BASKET_PRESERVING_SELECTED_ROUTE_MIX';
    if (basketContribution <= 0n) return {...base, ...details,
      reason:'The selected route mix has no positive contribution per basket. A higher volume cannot cover fixed costs or a positive contribution target.'};
    let requiredBaskets = ceil(fixed + netTarget, basketContribution);
    if (margin !== null) {
      if (basketGross === 0n) return {...base, ...details, reason:'A zero-gross route mix has no defined contribution margin.'};
      const denominator = basketContribution * MICRO - basketGross * margin;
      if (denominator < 0n || (denominator === 0n && fixed > 0n))
        return {...base, ...details, reason:'The route mix cannot reach the requested margin at these unit prices and fulfillment costs.'};
      const marginBaskets = denominator === 0n ? 1n : max(1n, ceil(fixed * MICRO, denominator));
      requiredBaskets = max(requiredBaskets, marginBaskets);
    }
    details.requiredBaskets = requiredBaskets.toString();
    const targets = new Map(basket.map(row => [row.routeId, row.requests * requiredBaskets]));
    details.volumes = current.metrics.routes.map(row => ({routeId:row.routeId,
      monthlyPaidTarget:(targets.get(row.routeId) ?? 0n).toString()}));
    if (details.volumes.some(row => BigInt(row.monthlyPaidTarget) > MAX_TARGET))
      return {...base, ...details, reason:'The required route volume exceeds the original analyzer\'s safe-integer monthly target range.'};
    for (const row of details.volumes) proposed.routes[row.routeId].monthlyPaidTarget = Number(row.monthlyPaidTarget);
  }

  const result = evaluate(context, proposed), goalMet = attainment(result.metrics, goal);
  if (goalMet.targetMet !== true) throw fail('SCENARIO_GOAL_UNRESOLVED', 'The original analyzer did not confirm the proposed planning goal.');
  return {...base, status:'READY', ...details, commercial:result.commercial, terms:result.terms,
    overview:result.overview, metrics:result.metrics, goalMet};
}

function goals(context, current, requested) {
  const breakEven = {monthlyContributionUsd:'0'};
  const suggestions = [suggestion(context, current, breakEven, 'BREAK_EVEN_PRICE'),
    suggestion(context, current, breakEven, 'BREAK_EVEN_VOLUME')];
  if (requested) suggestions.push(suggestion(context, current, requested, 'TARGET_PRICE'),
    suggestion(context, current, requested, 'TARGET_VOLUME'));
  return {requested, current:attainment(current.metrics, requested), suggestions};
}

function marginDifference(leftNet, leftGross, rightNet, rightGross) {
  const left = money(leftNet), right = money(rightNet), lg = money(leftGross), rg = money(rightGross);
  return left === null || right === null || lg === 0n || rg === 0n ? null
    : decimal((left * rg - right * lg) * MICRO / (lg * rg), 4);
}

function deltas(current, baseline) {
  const result = {plannedPaidRequests:(BigInt(current.metrics.plannedPaidRequests) - BigInt(baseline.metrics.plannedPaidRequests)).toString()};
  for (const field of ['grossUsd','variableCostsUsd','contributionBeforeFixedUsd','sharedFixedUsd','contributionAfterFixedUsd'])
    result[field] = difference(current.metrics[field], baseline.metrics[field]);
  result.marginBeforeFixedPercentagePoints = marginDifference(current.metrics.contributionBeforeFixedUsd,
    current.metrics.grossUsd, baseline.metrics.contributionBeforeFixedUsd, baseline.metrics.grossUsd);
  result.marginAfterFixedPercentagePoints = marginDifference(current.metrics.contributionAfterFixedUsd,
    current.metrics.grossUsd, baseline.metrics.contributionAfterFixedUsd, baseline.metrics.grossUsd);
  result.routeChanges = Object.keys(current.commercial.routes).flatMap(routeId => {
    const before = baseline.commercial.routes[routeId], after = current.commercial.routes[routeId];
    const fields = routeFields.filter(field => before[field] !== after[field]);
    return fields.length ? [{routeId, fields, before:clone(before), after:clone(after)}] : [];
  });
  return result;
}

/**
 * Review up to twelve explicit commercial plans against one immutable source.
 * The caller owns private version storage, byte-source hashes and the selected
 * plan's application. Every report and proposed goal uses the original analyzer.
 * Pass includeReports:false for compact comparisons: each full analyzer report
 * is released after extracting the source-bound calculations and terms. Full
 * and compact modes have the same review identity. The selected full report can
 * be generated again from these immutable inputs for its original HTML export.
 */
export function createScenarioReview({seller, observation, terms, scenarios = [], provenance = {}, includeReports = true} = {}) {
  record(provenance, 'source provenance');
  if (typeof includeReports !== 'boolean') throw fail('SCENARIO_INPUT_INVALID', 'includeReports must be a boolean.');
  if (!Array.isArray(scenarios) || scenarios.length > 12)
    throw fail('SCENARIO_COUNT_INVALID', 'A comparison accepts at most twelve scenarios.');
  const generatedAt = new Date().toISOString();
  // Validate the saved binding before normalizing any alternative. In particular,
  // merchantTerms must not be allowed to rebind stale source terms silently.
  const original = analyze(seller, observation, terms, clone(provenance));
  original.generatedAt = generatedAt;
  const sourceCommercial = commercial(terms);
  const source = {sellerCanonicalSha256:fingerprint(seller), observationCanonicalSha256:fingerprint(observation),
    termsCanonicalSha256:fingerprint(terms), provenance:clone(provenance)};
  const selectedRoutes = new Set(original.routes.map(row => row.routeId));
  const inputs = scenarios.map((value, index) => scenarioInput(value, index, sourceCommercial, selectedRoutes));
  if (new Set(inputs.map(value => value.id)).size !== inputs.length)
    throw fail('SCENARIO_ID_DUPLICATE', 'Every scenario in a comparison needs its own ID.');
  const context = {seller, observation, provenance, generatedAt};
  const baseline = {id:'baseline', label:'Saved review', input:null, commercial:sourceCommercial,
    terms:clone(terms), overview:original.overview, metrics:metrics(original),
    ...(includeReports ? {report:original} : {}), delta:null};
  baseline.goals = goals(context, baseline, null);
  const alternatives = inputs.map(input => {
    const result = evaluate(context, applyInput(sourceCommercial, input));
    if (!includeReports) delete result.report;
    const row = {id:input.id, label:input.label, input, ...result};
    row.delta = deltas(row, baseline);
    row.goals = goals(context, row, input.goal ?? null);
    return row;
  });
  return {schema:SCENARIO_REVIEW_SCHEMA, reviewSha256:fingerprint({schema:SCENARIO_REVIEW_SCHEMA, source, inputs}),
    source, generatedAt, baseline, scenarios:alternatives};
}

// MIT. Saved commercial comparisons over the original SF97 review and analyzer.
import { constants } from 'node:fs';
import { mkdir, open, lstat, realpath, readdir, link, unlink } from 'node:fs/promises';
import { join, resolve, isAbsolute } from 'node:path';
import { createHash, randomUUID } from 'node:crypto';
import { createScenarioReview } from './scenarios.mjs';

const SCHEMA = 'stellar-forge.merchant-scenario-plan.v1';
const UUID = /^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/;
const HASH = /^[a-f0-9]{64}$/;
const MAX_BYTES = 8 * 1024 * 1024;
const canonical = value => JSON.stringify(value, (_, item) => item && typeof item === 'object' && !Array.isArray(item)
  ? Object.fromEntries(Object.keys(item).sort().map(key => [key, item[key]])) : item);
const digest = value => createHash('sha256').update(value).digest('hex');
const encode = value => Buffer.from(JSON.stringify(value, null, 2) + '\n');
const fail = (code, message, status = 422) => Object.assign(new Error(message), {code, message, status});

async function privateDirectory(path, create = false) {
  if (create) await mkdir(path, {mode:0o700}).catch(error => { if (error.code !== 'EEXIST') throw error; });
  const stat = await lstat(path);
  if (!stat.isDirectory() || stat.mode & 0o077 || await realpath(path) !== path)
    throw fail('PRIVATE_PLANNING_DIRECTORY_REQUIRED', 'Use the existing private merchant workspace.');
}
async function syncDirectory(path) {
  const handle = await open(path, 'r');
  try { await handle.sync(); } finally { await handle.close(); }
}
function compactRow({report, ...row}) { return row; }
function compact(review) {
  return {...review, baseline:compactRow(review.baseline), scenarios:review.scenarios.map(compactRow)};
}
function summary(record) {
  return {planId:record.planId, label:record.label, savedAt:record.savedAt,
    version:record.version, sourceLabel:record.sourceLabel, selectedScenarioId:record.selectedScenarioId,
    scenarioCount:record.review.scenarios.length, reviewSha256:record.review.reviewSha256,
    source:record.source};
}

export async function openPlanningWorkspace({model, directory}) {
  if (!isAbsolute(directory ?? '') || resolve(directory) !== directory || directory === '/')
    throw fail('PRIVATE_PLANNING_DIRECTORY_REQUIRED', 'Use an absolute private merchant workspace.');
  await privateDirectory(directory);
  const plans = join(directory, 'scenario-plans'), pending = join(plans, 'pending');
  await privateDirectory(plans, true); await privateDirectory(pending, true);

  async function read(planId) {
    if (!UUID.test(planId ?? '')) throw fail('PLAN_NOT_FOUND', 'Choose a saved scenario plan.', 404);
    const handle = await open(join(plans, planId + '.json'), constants.O_RDONLY | (constants.O_NOFOLLOW ?? 0));
    try {
      const stat = await handle.stat();
      if (!stat.isFile() || stat.mode & 0o077 || stat.size > MAX_BYTES)
        throw fail('SAVED_PLAN_CHANGED', 'The saved comparison has changed type, permissions or size.');
      const bytes = await handle.readFile();
      if (bytes.length > MAX_BYTES) throw fail('SAVED_PLAN_CHANGED', 'The saved comparison exceeds its supported size.');
      const envelope = JSON.parse(bytes.toString('utf8')), record = envelope.record;
      if (!record || record.schema !== SCHEMA || record.planId !== planId ||
          !HASH.test(envelope.sha256 ?? '') || digest(canonical(record)) !== envelope.sha256 ||
          !UUID.test(record.version ?? '') || !Array.isArray(record.review?.scenarios))
        throw fail('SAVED_PLAN_CHANGED', 'The saved comparison differs from its committed record.');
      return record;
    } finally { await handle.close(); }
  }
  async function existing(planId) {
    try { return await read(planId); } catch (error) { if (error.code === 'ENOENT') return null; throw error; }
  }
  async function list() {
    const names = (await readdir(plans)).filter(name => UUID.test(name.slice(0, -5)) && name.endsWith('.json'));
    // Lists stay compact; every saved plan remains addressable by its original ID.
    const dated = [];
    for (const name of names) dated.push({name, date:(await lstat(join(plans,name))).mtimeMs});
    dated.sort((a,b) => b.date - a.date || a.name.localeCompare(b.name));
    const rows = [];
    for (const item of dated.slice(0,100)) rows.push(summary(await read(item.name.slice(0,-5))));
    rows.sort((a,b) => b.savedAt.localeCompare(a.savedAt) || a.planId.localeCompare(b.planId));
    return {total:names.length, plans:rows};
  }
  async function context(version) {
    if (!UUID.test(version ?? '')) throw fail('PRICING_REVIEW_REQUIRED', 'Choose a saved pricing review.');
    return model.planningSource(version);
  }
  async function source(version) {
    const value = await context(version);
    return {version:value.version,label:value.label,savedAt:value.savedAt,routes:value.routes,
      commercial:value.commercial,provenance:value.provenance,observation:value.observationSummary,
      sellerChanged:value.sellerChanged};
  }
  async function prepare(input) {
    if (!input || typeof input !== 'object' || Array.isArray(input))
      throw fail('SCENARIO_INPUT_REQUIRED', 'Supply the selected review and commercial scenarios.');
    const value = await context(input.version);
    const review = createScenarioReview({seller:value.seller,observation:value.observation,terms:value.terms,
      scenarios:input.scenarios,provenance:value.provenance,includeReports:false});
    return {value,review:compact(review)};
  }
  async function preview(input) {
    const {value,review} = await prepare(input);
    return {version:value.version,sourceLabel:value.label,sellerChanged:value.sellerChanged,review};
  }
  async function save(input) {
    if (!input || !UUID.test(input.requestId ?? '') || typeof input.label !== 'string' ||
        !input.label.trim() || input.label.trim().length > 100 || !HASH.test(input.reviewSha256 ?? ''))
      throw fail('PLAN_SAVE_DETAILS_REQUIRED', 'Review the scenarios and give the comparison a name before saving.');
    const request = {version:input.version,scenarios:input.scenarios,label:input.label.trim(),
      selectedScenarioId:input.selectedScenarioId ?? null,reviewSha256:input.reviewSha256};
    const requestSha256 = digest(canonical(request)), previous = await existing(input.requestId);
    function recover(record) {
      if (record.requestSha256 !== requestSha256)
        throw fail('PLAN_REQUEST_CHANGED', 'This save request already belongs to different scenario inputs.',409);
      return {status:'SCENARIO_PLAN_SAVED',recovered:true,...summary(record),record};
    }
    if (previous) return recover(previous);
    const {value,review} = await prepare(input);
    if (review.reviewSha256 !== input.reviewSha256)
      throw fail('SCENARIO_REVIEW_CHANGED', 'Calculate the current scenario inputs again before saving.',409);
    if (request.selectedScenarioId !== null && !review.scenarios.some(row => row.id === request.selectedScenarioId))
      throw fail('SCENARIO_SELECTION_REQUIRED', 'Choose one of this comparison’s scenarios.');
    const record = {schema:SCHEMA,planId:input.requestId,label:request.label,savedAt:new Date().toISOString(),
      version:value.version,sourceLabel:value.label,source:value.provenance,selectedScenarioId:request.selectedScenarioId,
      requestSha256,inputs:{scenarios:input.scenarios},review};
    const bytes = encode({sha256:digest(canonical(record)),record});
    if (bytes.length > MAX_BYTES)
      throw fail('SCENARIO_PLAN_TOO_LARGE', 'Save fewer scenarios in this comparison; each plan supports up to 8 MiB.');
    const staging = join(pending,randomUUID()+'.json'), final = join(plans,input.requestId+'.json');
    const handle = await open(staging,'wx',0o600);
    try { await handle.writeFile(bytes); await handle.sync(); }
    catch (error) { await unlink(staging).catch(()=>{}); throw error; }
    finally { await handle.close(); }
    try {
      try { await link(staging,final); }
      catch (error) { if (error.code === 'EEXIST') return recover(await read(input.requestId)); throw error; }
      await syncDirectory(plans);
      return {status:'SCENARIO_PLAN_SAVED',recovered:false,...summary(record),record};
    } finally { await unlink(staging).catch(()=>{}); }
  }
  async function load(planId) { return read(planId); }
  async function selection({planId,scenarioId} = {}) {
    const record = await read(planId), row = record.review.scenarios.find(item => item.id === scenarioId);
    if (!row) throw fail('SCENARIO_NOT_FOUND', 'Choose a saved scenario from this comparison.',404);
    // Applying is a new draft in the existing workspace; its normal save keeps
    // the current capture and revision. A different seller requires a new plan.
    const current = await model.loadVersion(record.version);
    if (current.sellerSha256 !== record.source.seller)
      throw fail('SCENARIO_SELLER_CHANGED', 'The seller configuration changed. Save a current pricing review and create a new comparison before applying this plan.',409);
    return {planId,scenarioId,label:record.label,scenarioLabel:row.label,version:record.version,
      sellerSha256:current.sellerSha256,commercial:structuredClone(row.commercial),
      reviewSha256:record.review.reviewSha256};
  }
  async function download(planId, name) {
    const record = await read(planId);
    if (name === 'plan.json') return encode(record);
    if (name === 'comparison.csv') {
      const quote = value => '"'+String(value ?? '').replaceAll('"','""')+'"';
      const rows = [record.review.baseline,...record.review.scenarios];
      const data = [['Scenario','Planned paid requests','Gross USD','Variable cost USD','Contribution before fixed USD',
        'Fixed cost USD','Contribution after fixed USD','Margin after fixed percent','Source review'],
      ...rows.map(row => [/^[=+\-@\t\r]/.test(row.label) ? "'"+row.label : row.label,row.metrics.plannedPaidRequests,row.metrics.grossUsd,row.metrics.variableCostsUsd,
        row.metrics.contributionBeforeFixedUsd,row.metrics.sharedFixedUsd,row.metrics.contributionAfterFixedUsd,
        row.metrics.marginAfterFixedPct,record.version])];
      return Buffer.from('\uFEFF'+data.map(row => row.map(quote).join(',')).join('\r\n')+'\r\n');
    }
    const match = /^terms-([a-zA-Z0-9_-]+)\.json$/.exec(name);
    const row = match && record.review.scenarios.find(item => item.id === match[1]);
    if (row) return encode(row.terms);
    throw fail('PLAN_FILE_NOT_FOUND', 'Choose a file from this saved comparison.',404);
  }
  return {source,preview,save,load,selection,list,download};
}

// MIT. Exact monthly tariff planning over the original SF97 merchant review.
import { createHash } from 'node:crypto';
import { analyze } from '../analyze.mjs';

export const TARIFF_REVIEW_SCHEMA = 'stellar-forge.merchant-tariff-review.v1';
export const TARIFF_QUOTE_SCHEMA = 'stellar-forge.merchant-tariff-quote.v1';
export const TARIFF_LIMITS = Object.freeze({ tariffs:12, volumes:24, tiers:64 });

const MICRO = 1_000_000n;
const MAX_QUANTITY = BigInt(Number.MAX_SAFE_INTEGER);
const plain = value => value !== null && typeof value === 'object' && !Array.isArray(value)
  && [Object.prototype, null].includes(Object.getPrototypeOf(value));
const canonical = value => JSON.stringify(value, (_, item) => plain(item)
  ? Object.fromEntries(Object.keys(item).sort().map(key => [key, item[key]])) : item);
const fingerprint = value => createHash('sha256').update(canonical(value)).digest('hex');
const fail = (code, message, status = 422) => Object.assign(new TypeError(message), { code, status });
const clone = value => structuredClone(value);

function record(value, label, fields = null) {
  if (!plain(value)) throw fail('TARIFF_INPUT_INVALID', label + ' must be an object.');
  if (fields) {
    const unsupported = Object.keys(value).find(key => !fields.includes(key));
    if (unsupported) throw fail('TARIFF_INPUT_INVALID', label + ' has an unsupported field: ' + unsupported + '.');
  }
  return value;
}

function quantity(value, label = 'Quantity') {
  let number;
  if (typeof value === 'number' && Number.isSafeInteger(value) && value >= 0) number = BigInt(value);
  else if (typeof value === 'string' && /^(0|[1-9]\d{0,15})$/.test(value)) number = BigInt(value);
  else throw fail('TARIFF_QUANTITY_INVALID', label + ' must be a nonnegative safe integer or its canonical integer string.');
  if (number > MAX_QUANTITY)
    throw fail('TARIFF_QUANTITY_INVALID', label + ' exceeds the original merchant monthly target range.');
  return number;
}

function microUsd(value, label = 'USD amount') {
  if (typeof value !== 'string' || !/^(0|[1-9]\d*)(\.\d{1,6})?$/.test(value))
    throw fail('TARIFF_AMOUNT_INVALID', label + ' must be a nonnegative USD decimal string with at most six places.');
  const [whole, fraction = ''] = value.split('.');
  return BigInt(whole) * MICRO + BigInt(fraction.padEnd(6, '0'));
}

function decimal(value, places = 6) {
  if (value === null) return null;
  const scale = 10n ** BigInt(places), negative = value < 0n, absolute = negative ? -value : value;
  const tail = String(absolute % scale).padStart(places, '0').replace(/0+$/, '');
  return (negative ? '-' : '') + String(absolute / scale) + (tail ? '.' + tail : '');
}

const usd = value => decimal(value, 6);
const ceil = (numerator, denominator) => (numerator + denominator - 1n) / denominator;
const min = (left, right) => left < right ? left : right;

function gcd(left, right) {
  while (right) [left, right] = [right, left % right];
  return left;
}

// Fractions are authoritative; the display bounds retain twelve decimal places.
function unitFraction(totalMicroUsd, units) {
  if (!units) return null;
  const denominator = units * MICRO, divisor = gcd(totalMicroUsd, denominator);
  const scaled = totalMicroUsd * 1_000_000_000_000n;
  return {
    numerator:String(totalMicroUsd / divisor), denominator:String(denominator / divisor),
    floorUsd:decimal(scaled / denominator, 12), ceilingUsd:decimal(ceil(scaled, denominator), 12)
  };
}

function margin(contribution, gross) {
  return contribution === null || gross === 0n ? null : decimal(contribution * MICRO / gross, 4);
}

/**
 * Each upTo is a cumulative inclusive quantity. The final null is unbounded.
 * A graduated schedule prices each band separately. A volume schedule selects
 * one band from the entire monthly quantity and applies its rate to all units.
 */
export function normalizeTariff(input) {
  record(input, 'Tariff', ['id', 'label', 'routeId', 'mode', 'tiers']);
  if (typeof input.id !== 'string' || !/^[A-Za-z0-9][A-Za-z0-9_-]{0,63}$/.test(input.id) || input.id === 'baseline')
    throw fail('TARIFF_ID_INVALID', 'Use a tariff ID of 1-64 letters, digits, underscores or hyphens; baseline is reserved.');
  if (typeof input.label !== 'string' || !input.label.trim() || input.label.length > 120
      || /[\u0000-\u001f\u007f]/.test(input.label))
    throw fail('TARIFF_LABEL_INVALID', 'Give each tariff a label of 1-120 printable characters.');
  if (typeof input.routeId !== 'string' || !input.routeId || input.routeId.length > 2000
      || /[\u0000-\u001f\u007f]/.test(input.routeId))
    throw fail('TARIFF_ROUTE_INVALID', 'Select an original merchant route ID.');
  if (!['graduated', 'volume'].includes(input.mode))
    throw fail('TARIFF_MODE_INVALID', 'Choose graduated or volume pricing.');
  if (!Array.isArray(input.tiers) || !input.tiers.length || input.tiers.length > TARIFF_LIMITS.tiers)
    throw fail('TARIFF_TIERS_INVALID', 'A tariff needs 1-' + TARIFF_LIMITS.tiers + ' tiers.');

  let previous = 0n;
  const tiers = input.tiers.map((tier, index) => {
    record(tier, 'Tier ' + (index + 1), ['upTo', 'unitPriceUsd']);
    const last = index === input.tiers.length - 1;
    if (last ? tier.upTo !== null : tier.upTo === null)
      throw fail('TARIFF_BAND_INVALID', 'Only the final tier has an unbounded null upTo.');
    let cap = null;
    if (tier.upTo !== null) {
      cap = quantity(tier.upTo, 'Tier ' + (index + 1) + ' upper quantity');
      if (cap <= previous)
        throw fail('TARIFF_BAND_INVALID', 'Finite tier quantities must be positive and strictly increasing.');
      previous = cap;
    }
    if (typeof tier.unitPriceUsd !== 'string' || tier.unitPriceUsd.length > 64)
      throw fail('TARIFF_AMOUNT_INVALID', 'Tier unit price must be a USD string of at most 64 characters.');
    const rate = microUsd(tier.unitPriceUsd, 'Tier ' + (index + 1) + ' unit price');
    return { upTo:cap === null ? null : String(cap), unitPriceUsd:usd(rate) };
  });
  return { id:input.id, label:input.label.trim(), routeId:input.routeId, mode:input.mode, tiers };
}

function calculate(tariff, units) {
  if (!units) return { total:0n, lines:[], selectedTier:null };
  let lower = 0n, total = 0n, selectedTier = null;
  const lines = [];
  for (let index = 0; index < tariff.tiers.length; index++) {
    const tier = tariff.tiers[index], cap = tier.upTo === null ? null : BigInt(tier.upTo);
    const price = microUsd(tier.unitPriceUsd);
    if (tariff.mode === 'volume') {
      if (cap !== null && units > cap) { lower = cap; continue; }
      total = units * price;
      lines.push({ tierIndex:index, lowerExclusiveQuantity:String(lower), upTo:tier.upTo,
        quantity:String(units), unitPriceUsd:tier.unitPriceUsd, subtotalUsd:usd(total) });
      selectedTier = index;
      break;
    }
    const upper = cap === null ? units : min(units, cap), used = upper - lower;
    if (used > 0n) {
      const subtotal = used * price;
      total += subtotal;
      lines.push({ tierIndex:index, lowerExclusiveQuantity:String(lower), upTo:tier.upTo,
        quantity:String(used), unitPriceUsd:tier.unitPriceUsd, subtotalUsd:usd(subtotal) });
      selectedTier = index;
    }
    if (units <= upper) break;
    lower = cap;
  }
  return { total, lines, selectedTier };
}

/** Exact schedule result and the separately derived six-place uniform quote. */
export function quoteTariff(input, requestedQuantity) {
  const tariff = normalizeTariff(input), units = quantity(requestedQuantity);
  const calculation = calculate(tariff, units);
  const uniform = units ? ceil(calculation.total, units) : null;
  const uniformGross = uniform === null ? null : uniform * units;
  const next = units < MAX_QUANTITY ? calculate(tariff, units + 1n) : null;
  return {
    schema:TARIFF_QUOTE_SCHEMA, tariffId:tariff.id, tariffSha256:fingerprint(tariff), mode:tariff.mode,
    quantity:String(units), totalMicroUsd:String(calculation.total), totalUsd:usd(calculation.total),
    selectedTier:calculation.selectedTier, lines:calculation.lines,
    effectiveUnitUsd:unitFraction(calculation.total, units),
    chosenUniformQuoteUsd:usd(uniform), uniformGrossUsd:usd(uniformGross),
    roundingDeltaUsd:uniformGross === null ? null : usd(uniformGross - calculation.total),
    rounding:'CEILING_TO_MICRO_USD_PER_REQUEST',
    nextQuantity:next === null ? null : String(units + 1n),
    nextTotalUsd:next === null ? null : usd(next.total),
    nextGrossChangeUsd:next === null ? null : usd(next.total - calculation.total),
    nextUnitPriceUsd:next === null ? null : tariff.tiers[next.selectedTier].unitPriceUsd
  };
}

function boundaries(tariff) {
  return tariff.tiers.flatMap((tier, index) => {
    if (tier.upTo === null || BigInt(tier.upTo) === MAX_QUANTITY) return [];
    const beforeQuantity = BigInt(tier.upTo), before = calculate(tariff, beforeQuantity);
    const after = calculate(tariff, beforeQuantity + 1n), change = after.total - before.total;
    return [{
      afterTierIndex:index, beforeQuantity:String(beforeQuantity), afterQuantity:String(beforeQuantity + 1n),
      beforeTotalUsd:usd(before.total), afterTotalUsd:usd(after.total),
      grossChangeUsd:usd(change), decreasesGross:change < 0n
    }];
  });
}

function scenarioFor(tariff, quote, comparisonId) {
  if (quote.quantity === '0') return null;
  return {
    id:comparisonId,
    label:(tariff.label.slice(0, 75) + ' at ' + quote.quantity + ' requests/month').slice(0, 120),
    routes:{
      [tariff.routeId]:{
        unitPriceUsd:quote.chosenUniformQuoteUsd,
        priceBasis:'Uniform quote from ' + tariff.mode + ' tariff ' + quote.tariffSha256
          + ' at ' + quote.quantity + ' planned requests/month; CEILING(total micro-USD / quantity).',
        monthlyPaidTarget:Number(quote.quantity)
      }
    }
  };
}

function comparison(tariff, requestedQuantity, row, reviewSha256) {
  const quote = quoteTariff(tariff, requestedQuantity), units = BigInt(quote.quantity);
  const baselineGross = microUsd(row.quoteUsd) * units;
  const unitCost = row.variablePerFulfilledUsd === null ? null : microUsd(row.variablePerFulfilledUsd);
  const cost = unitCost === null ? null : unitCost * units;
  const gross = BigInt(quote.totalMicroUsd);
  const baselineContribution = cost === null ? null : baselineGross - cost;
  const contribution = cost === null ? null : gross - cost;
  const uniformGross = quote.uniformGrossUsd === null ? null : microUsd(quote.uniformGrossUsd);
  const uniformContribution = uniformGross === null || cost === null ? null : uniformGross - cost;
  const comparisonId = fingerprint({ reviewSha256, tariffId:tariff.id, quantity:quote.quantity });
  return {
    id:comparisonId, tariffId:tariff.id, routeId:tariff.routeId, quantity:quote.quantity,
    method:row.method, path:row.path, quote,
    baseline:{
      quoteUsd:row.quoteUsd, priceBasis:row.priceBasis, totalUsd:usd(baselineGross),
      contributionBeforeFixedUsd:usd(baselineContribution),
      marginBeforeFixedPct:margin(baselineContribution, baselineGross)
    },
    costs:{
      basis:'FULFILLED_REQUESTS_ONLY', perFulfilledUsd:row.variablePerFulfilledUsd,
      perChallengeUsd:row.perChallengeUsd, variableCostsUsd:usd(cost),
      unknownInputs:unitCost === null ? ['routes.' + tariff.routeId + '.perFulfilledUsd'] : []
    },
    contributionBeforeFixedUsd:usd(contribution), marginBeforeFixedPct:margin(contribution, gross),
    grossDeltaUsd:usd(gross - baselineGross),
    contributionDeltaUsd:cost === null ? null : usd(contribution - baselineContribution),
    uniformProjection:{
      grossUsd:usd(uniformGross), variableCostsUsd:quote.quantity === '0' ? null : usd(cost),
      contributionBeforeFixedUsd:usd(uniformContribution),
      marginBeforeFixedPct:uniformGross === null ? null : margin(uniformContribution, uniformGross),
      grossDeltaUsd:uniformGross === null ? null : usd(uniformGross - baselineGross)
    },
    scenario:scenarioFor(tariff, quote, comparisonId)
  };
}

/**
 * Evaluate explicit monthly targets from the saved native seller review.
 * The original analyzer validates payment bindings and selected route scope.
 * Each comparison changes one route at one volume; shared fixed cost remains
 * on the whole-seller review. Explicit selection passes the included scenario
 * to the original planner, which calculates the complete merchant forecast.
 */
export function createTariffReview({ seller, observation, terms, tariffs, volumes, provenance = {} } = {}) {
  record(provenance, 'Source provenance');
  if (!Array.isArray(tariffs) || !tariffs.length || tariffs.length > TARIFF_LIMITS.tariffs)
    throw fail('TARIFF_COUNT_INVALID', 'Compare 1-' + TARIFF_LIMITS.tariffs + ' tariff schedules.');
  if (!Array.isArray(volumes) || !volumes.length || volumes.length > TARIFF_LIMITS.volumes)
    throw fail('TARIFF_VOLUMES_INVALID', 'Enter 1-' + TARIFF_LIMITS.volumes + ' explicit monthly quantities.');
  const normalized = tariffs.map(normalizeTariff);
  if (new Set(normalized.map(tariff => tariff.id)).size !== normalized.length)
    throw fail('TARIFF_ID_DUPLICATE', 'Every tariff in a review needs its own ID.');
  const quantities = volumes.map((value, index) => String(quantity(value, 'Monthly quantity ' + (index + 1))));
  if (new Set(quantities).size !== quantities.length)
    throw fail('TARIFF_VOLUME_DUPLICATE', 'Each monthly quantity must appear once in a review.');

  // Preserve the analyzer's exact checks before using any commercial term.
  const original = analyze(seller, observation, terms, clone(provenance));
  const byRoute = new Map(original.routes.map(row => [row.routeId, row]));
  const sellerRoutes = new Set(seller.routes.map(route => route.id));
  for (const tariff of normalized) {
    if (!sellerRoutes.has(tariff.routeId))
      throw fail('TARIFF_ROUTE_UNKNOWN', 'The saved seller has no route ' + tariff.routeId + '.');
    if (!byRoute.has(tariff.routeId))
      throw fail('TARIFF_ROUTE_OUTSIDE_REVIEW', 'Route ' + tariff.routeId + ' is outside the saved review route selection.');
  }
  const source = {
    sellerCanonicalSha256:fingerprint(seller), observationCanonicalSha256:fingerprint(observation),
    termsCanonicalSha256:fingerprint(terms), provenance:clone(provenance)
  };
  const tariffReviewSha256 = fingerprint({ schema:TARIFF_REVIEW_SCHEMA, source, tariffs:normalized, volumes:quantities });
  const comparisons = normalized.flatMap(tariff => quantities.map(value =>
    comparison(tariff, value, byRoute.get(tariff.routeId), tariffReviewSha256)));
  return {
    schema:TARIFF_REVIEW_SCHEMA, tariffReviewSha256, source, generatedAt:new Date().toISOString(),
    tariffs:normalized, volumes:quantities, comparisons,
    tariffDetails:normalized.map(tariff => ({
      tariffId:tariff.id, tariffSha256:fingerprint(tariff), boundaries:boundaries(tariff)
    })),
    baseline:{
      merchantName:terms.merchantName,
      scope:original.overview.sharedFixedCostApplied === false ? 'SELECTED_CURRENT_ROUTE' : 'CURRENT_SELLER',
      sharedMonthlyFixedUsd:original.overview.sharedMonthlyFixedUsd,
      sharedFixedCostApplied:original.overview.sharedFixedCostApplied !== false,
      monthlyTargets:Object.fromEntries(original.routes.map(row => [row.routeId, row.paidTargetMonth]))
    }
  };
}

/** Return a mutable copy for the caller's explicit original-plan selection. */
export function selectionScenario(review, comparisonId) {
  record(review, 'Tariff review');
  if (review.schema !== TARIFF_REVIEW_SCHEMA || !/^[a-f0-9]{64}$/.test(review.tariffReviewSha256 ?? '')
      || !Array.isArray(review.comparisons))
    throw fail('TARIFF_REVIEW_INVALID', 'Use a complete saved tariff review.');
  if (typeof comparisonId !== 'string' || !/^[a-f0-9]{64}$/.test(comparisonId))
    throw fail('TARIFF_COMPARISON_NOT_FOUND', 'Select a comparison from this tariff review.', 404);
  const row = review.comparisons.find(item => item.id === comparisonId);
  if (!row) throw fail('TARIFF_COMPARISON_NOT_FOUND', 'The selected comparison is unavailable in this review.', 404);
  if (row.quantity === '0' || row.scenario === null)
    throw fail('TARIFF_ZERO_VOLUME', 'A uniform per-request quote requires a positive monthly quantity.');
  const expectedId = fingerprint({ reviewSha256:review.tariffReviewSha256, tariffId:row.tariffId, quantity:row.quantity });
  if (row.id !== expectedId || !plain(row.scenario) || row.scenario.id !== row.id)
    throw fail('TARIFF_REVIEW_INVALID', 'The selected comparison differs from its saved tariff identity.');
  return clone(row.scenario);
}

// MIT. Tariff plans over the original merchant pricing and scenario workspaces.
import { constants } from 'node:fs';
import { mkdir, open, lstat, realpath, readdir, link, unlink } from 'node:fs/promises';
import { resolve, join, isAbsolute } from 'node:path';
import { createHash, randomUUID } from 'node:crypto';
import { createTariffReview } from './model.mjs';
import { createScenarioReview } from '../planning/scenarios.mjs';
import { openPlanningWorkspace } from '../planning/workspace.mjs';

const PLAN = 'stellar-forge.merchant-tariff-plan.v1';
const BUNDLE = 'stellar-forge.merchant-tariff-portfolio.v1';
const SELECTION = 'stellar-forge.merchant-tariff-selection.v1';
const UUID = /^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/;
const HASH = /^[a-f0-9]{64}$/;
const MAX_FILE = 16 * 1024 * 1024;
const MAX_BUNDLE = 64 * 1024 * 1024;
const copy = value => structuredClone(value);
const object = value => value && typeof value === 'object' && !Array.isArray(value);
const canonical = value => JSON.stringify(value, (_, item) => object(item)
  ? Object.fromEntries(Object.keys(item).sort().map(key => [key, item[key]])) : item);
const hash = value => createHash('sha256').update(value).digest('hex');
const fingerprint = value => hash(canonical(value));
const encode = value => Buffer.from(JSON.stringify(value, null, 2) + '\n');
const fault = (code, message, status = 422) => Object.assign(new Error(message), {code, status});
const absent = error => error.code === 'ENOENT';
function id(value, label = 'plan') {
  if (!UUID.test(value ?? '')) throw fault('TARIFF_ID_REQUIRED', 'Choose a valid ' + label + ' UUID.');
  return value;
}
async function privateDirectory(path, create = false) {
  if (create) await mkdir(path, {mode:0o700}).catch(error => { if (error.code !== 'EEXIST') throw error; });
  const stat = await lstat(path);
  if (!stat.isDirectory() || (stat.mode & 0o077) || await realpath(path) !== path)
    throw fault('PRIVATE_TARIFF_DIRECTORY_REQUIRED', 'Use the existing private merchant pricing workspace.');
}
async function syncDirectory(path) {
  const handle = await open(path, 'r');
  try { await handle.sync(); } finally { await handle.close(); }
}
function summary(record) {
  return {planId:record.planId, label:record.label, savedAt:record.savedAt, version:record.version,
    sourceLabel:record.sourceLabel, tariffReviewSha256:record.review.tariffReviewSha256,
    tariffCount:record.inputs.tariffs.length, comparisonCount:record.review.comparisons.length};
}
function stableReview(review) {
  const value = copy(review);
  delete value.generatedAt;
  return value;
}
function stableSelection(selection) {
  if (!object(selection)) throw fault('TARIFF_SELECTION_REQUIRED', 'Review one saved tariff comparison.');
  return {schema:selection.schema, planId:selection.planId, comparisonId:selection.comparisonId,
    tariffReviewSha256:selection.tariffReviewSha256, sourceSelection:selection.sourceSelection,
    scenarioPlanInput:selection.scenarioPlanInput, pricingInput:selection.pricingInput};
}

/** The original complete receiving preflight, callable with retained read-only source providers. */
export async function inspectTariffPortfolio(raw,{pricingSource,scenarioPlan,pricingManifest,retainedTariffPlan}={}) {
    if(typeof pricingSource!=='function'||typeof scenarioPlan!=='function'||typeof pricingManifest!=='function')
      throw fault('TARIFF_PORTFOLIO_SOURCE_REQUIRED','Use the original saved pricing, scenario and manifest readers.');
    const input = copy(raw);
    if (!object(input) || input.schema !== BUNDLE || !Array.isArray(input.plans) || !Array.isArray(input.selections) ||
        !HASH.test(input.sha256 ?? '') || encode(input).length > MAX_BUNDLE ||
        fingerprint({schema:input.schema,plans:input.plans,selections:input.selections}) !== input.sha256)
      throw fault('TARIFF_PORTFOLIO_INVALID','Use the complete exported tariff portfolio.');

    const timestamp = value => typeof value === 'string' && Number.isFinite(Date.parse(value)) &&
      new Date(value).toISOString() === value;
    const invalid = message => fault('TARIFF_PORTFOLIO_INVALID', message);
    const sourceChanged = message => fault('TARIFF_PORTFOLIO_SOURCE_CHANGED', message, 409);
    const plans = new Map(), journals = [], requestBodies = new Map();

    async function inspectPlan(record) {
      id(record?.planId); id(record?.version, 'pricing review');
      if (record.schema !== PLAN || !object(record.inputs) ||
          Object.keys(record.inputs).some(key => !['tariffs','volumes'].includes(key)) ||
          typeof record.label !== 'string' || !record.label.trim() ||
          record.label !== record.label.trim() || record.label.length > 100 ||
          !timestamp(record.savedAt) || !timestamp(record.review?.generatedAt) ||
          !HASH.test(record.requestSha256 ?? '') || !HASH.test(record.review?.tariffReviewSha256 ?? ''))
        throw invalid('A tariff plan is incomplete or its saved request identity is invalid.');
      const request = {version:record.version,tariffs:record.inputs.tariffs,volumes:record.inputs.volumes,
        label:record.label,tariffReviewSha256:record.review.tariffReviewSha256};
      if (fingerprint(request) !== record.requestSha256)
        throw invalid('A tariff plan no longer matches its original save request.');
      const value = await pricingSource(record.version);
      const review = createTariffReview({seller:value.seller,observation:value.observation,terms:value.terms,
        tariffs:record.inputs.tariffs,volumes:record.inputs.volumes,provenance:value.provenance});
      if (record.sourceLabel !== value.label || fingerprint(value.provenance) !== fingerprint(record.provenance) ||
          fingerprint(stableReview(review)) !== fingerprint(stableReview(record.review)))
        throw sourceChanged('Restore the matching original pricing backup before receiving these tariffs.');
      return {record,value};
    }

    // Preflight the complete incoming portfolio before registering any new plan
    // or resumable intent. Source reads use its immutable saved pricing versions.
    for (const record of input.plans) {
      id(record?.planId);
      if (plans.has(record.planId)) throw invalid('A tariff plan ID occurs more than once in this portfolio.');
      plans.set(record.planId, await inspectPlan(record));
    }

    async function originalPlan(planId) {
      id(planId);
      if (!plans.has(planId)) {
        if(typeof retainedTariffPlan!=='function')throw invalid('The portfolio omits its original tariff plan.');
        plans.set(planId, await inspectPlan(await retainedTariffPlan(planId)));
      }
      const found = plans.get(planId);
      if (!found.manifest) found.manifest = JSON.parse((await pricingManifest(found.record.version)).toString('utf8'));
      return found;
    }

    const selectionIds = new Set();
    for (const item of input.selections) {
      id(item?.id, 'pricing request');
      if (selectionIds.has(item.id)) throw invalid('A pricing request ID occurs more than once in this portfolio.');
      selectionIds.add(item.id);
      const intent = item.intent, request = intent?.request;
      if (!object(intent) || intent.schema !== 'stellar-forge.merchant-tariff-selection-intent.v1' ||
          !timestamp(intent.createdAt) || !object(request) || !object(intent.selection) ||
          !object(intent.scenarioRequest) || !object(intent.pricingRequest) ||
          (item.result !== null && !object(item.result)))
        throw invalid('A selection journal is incomplete.');
      id(request.planRequestId, 'scenario request'); id(request.pricingRequestId, 'pricing request');
      const core = stableSelection(request.selection);
      if (core.schema !== SELECTION || !object(core.scenarioPlanInput) || !object(core.pricingInput) ||
          !HASH.test(request.selection.selectionSha256 ?? '') ||
          fingerprint(core) !== request.selection.selectionSha256 ||
          !HASH.test(intent.requestSha256 ?? '') || fingerprint(request) !== intent.requestSha256 ||
          request.pricingRequestId !== item.id || fingerprint(intent.selection) !== fingerprint(core))
        throw invalid('A selection journal differs from its original selection and request IDs.');
      const normalizedRequest = {selection:{...core,selectionSha256:request.selection.selectionSha256},
        planRequestId:request.planRequestId,pricingRequestId:request.pricingRequestId};
      const scenarioRequest = {...core.scenarioPlanInput,requestId:request.planRequestId};
      const pricingRequest = {...core.pricingInput,requestId:request.pricingRequestId};
      if (fingerprint(request) !== fingerprint(normalizedRequest) ||
          fingerprint(intent.scenarioRequest) !== fingerprint(scenarioRequest) ||
          fingerprint(intent.pricingRequest) !== fingerprint(pricingRequest))
        throw invalid('The retained native request bodies do not belong to this tariff selection.');
      if (!(core.pricingInput.expectedRevision === null || HASH.test(core.pricingInput.expectedRevision ?? '')) ||
          !HASH.test(core.pricingInput.snapshotSha256 ?? '') || !HASH.test(core.pricingInput.sellerSha256 ?? ''))
        throw invalid('The selected native pricing revision or source capture is invalid.');

      const {record,value,manifest} = await originalPlan(core.planId);
      const row = record.review.comparisons.find(comparison => comparison.id === core.comparisonId);
      if (!row?.scenario) throw invalid('A selection journal does not identify an adoptable tariff comparison.');
      // Historical completed operations remain recoverable when today's seller
      // differs. These equations use the saved seller, terms and observations.
      const review = createScenarioReview({seller:value.seller,observation:value.observation,terms:value.terms,
        scenarios:[row.scenario],provenance:value.provenance,includeReports:false});
      const label = (record.label + ' / ' + row.quantity + ' requests').slice(0,100);
      const expectedPlan = {version:record.version,scenarios:[row.scenario],label,
        selectedScenarioId:row.scenario.id,reviewSha256:review.reviewSha256};
      const expectedPricing = {expectedRevision:core.pricingInput.expectedRevision,label,
        sellerSha256:record.provenance.seller,snapshotSha256:core.pricingInput.snapshotSha256,
        commercial:copy(review.scenarios[0].commercial)};
      const sourceSelection = manifest.sourceSelection ??
        {kind:manifest.observationKind ?? 'SESSION',from:null,to:null,routeId:null};
      if (core.tariffReviewSha256 !== record.review.tariffReviewSha256 ||
          fingerprint(core.sourceSelection) !== fingerprint(sourceSelection) ||
          fingerprint(core.scenarioPlanInput) !== fingerprint(expectedPlan) ||
          fingerprint(core.pricingInput) !== fingerprint(expectedPricing))
        throw invalid('A retained selection does not match its original tariff, scenario or merchant quote.');
      const normalizedScenarioRequest = {version:scenarioRequest.version,scenarios:scenarioRequest.scenarios,
        label:scenarioRequest.label.trim(),selectedScenarioId:scenarioRequest.selectedScenarioId ?? null,
        reviewSha256:scenarioRequest.reviewSha256};
      const scenarioRequestSha256 = fingerprint(normalizedScenarioRequest);
      if (requestBodies.has(request.planRequestId) && requestBodies.get(request.planRequestId) !== scenarioRequestSha256)
        throw invalid('One scenario request ID identifies different native scenario inputs.');
      requestBodies.set(request.planRequestId, scenarioRequestSha256);

      if (item.result !== null) {
        const result = item.result, actualPlan = await scenarioPlan(request.planRequestId);
        const version = id(result.pricing?.version, 'pricing review');
        const nativeManifestBytes = await pricingManifest(version);
        const nativeManifest = JSON.parse(nativeManifestBytes.toString('utf8'));
        if (result.status !== 'TARIFF_SELECTION_SAVED' || result.planId !== core.planId ||
            result.comparisonId !== core.comparisonId || actualPlan.planId !== request.planRequestId ||
            result.scenarioPlan?.planId !== actualPlan.planId ||
            actualPlan.requestSha256 !== scenarioRequestSha256 ||
            result.scenarioPlan?.reviewSha256 !== actualPlan.review.reviewSha256 ||
            result.scenarioPlan?.version !== actualPlan.version ||
            nativeManifest.version !== version || nativeManifest.requestId !== request.pricingRequestId ||
            nativeManifest.requestSha256 !== fingerprint(pricingRequest) ||
            result.pricing.revision !== hash(nativeManifestBytes))
          throw sourceChanged('Restore the exact original scenario and saved quote before receiving its completed selection.');
      }
      journals.push(item);
    }

    return {schema:'stellar-forge.merchant-tariff-portfolio-review.v1',sha256:input.sha256,
      plans:input.plans,selections:journals};
}

export async function openTariffWorkspace({model, directory} = {}) {
  if (!model || !isAbsolute(directory ?? '') || resolve(directory) !== directory || directory === '/')
    throw fault('PRIVATE_TARIFF_DIRECTORY_REQUIRED', 'Supply the original pricing model and absolute private workspace.');
  await privateDirectory(directory);
  const root = join(directory, 'tariff-plans'), pending = join(root, 'pending');
  const intents = join(root, 'selections'), results = join(root, 'selection-results');
  for (const path of [root, pending, intents, results]) await privateDirectory(path, true);
  const planning = await openPlanningWorkspace({model, directory});

  async function read(path) {
    const handle = await open(path, constants.O_RDONLY | (constants.O_NOFOLLOW ?? 0));
    try {
      const stat = await handle.stat();
      if (!stat.isFile() || (stat.mode & 0o077) || stat.size > MAX_FILE)
        throw fault('TARIFF_RECORD_CHANGED', 'A saved tariff record changed type, permissions or size.');
      const bytes = await handle.readFile();
      if (bytes.length > MAX_FILE) throw fault('TARIFF_RECORD_CHANGED', 'The tariff record exceeds its supported size.');
      const envelope = JSON.parse(bytes.toString('utf8'));
      if (!HASH.test(envelope.sha256 ?? '') || fingerprint(envelope.record) !== envelope.sha256)
        throw fault('TARIFF_RECORD_CHANGED', 'The tariff record differs from its saved contents.');
      return envelope.record;
    } finally { await handle.close(); }
  }
  async function maybe(path) {
    try { return await read(path); } catch (error) { if (absent(error)) return null; throw error; }
  }
  async function writeOnce(path, record) {
    const bytes = encode({sha256:fingerprint(record), record});
    if (bytes.length > MAX_FILE) throw fault('TARIFF_RECORD_TOO_LARGE', 'Save a smaller tariff comparison.');
    const staging = join(pending, randomUUID() + '.json');
    const handle = await open(staging, 'wx', 0o600);
    try { await handle.writeFile(bytes); await handle.sync(); }
    catch (error) { await unlink(staging).catch(() => {}); throw error; }
    finally { await handle.close(); }
    try {
      try { await link(staging, path); }
      catch (error) {
        if (error.code !== 'EEXIST') throw error;
        const before = await read(path);
        if (fingerprint(before) !== fingerprint(record))
          throw fault('TARIFF_REQUEST_CHANGED', 'This request already belongs to different saved inputs.', 409);
        return {record:before, recovered:true};
      }
      await syncDirectory(path.slice(0, path.lastIndexOf('/')));
      return {record, recovered:false};
    } finally { await unlink(staging).catch(() => {}); }
  }
  async function load(planId) {
    const record = await read(join(root, id(planId) + '.json')).catch(error => {
      if (absent(error)) throw fault('TARIFF_PLAN_NOT_FOUND', 'The saved tariff plan was not found.', 404);
      throw error;
    });
    if (record.schema !== PLAN || record.planId !== planId || !UUID.test(record.version ?? '') ||
        !object(record.inputs) || !Array.isArray(record.review?.comparisons))
      throw fault('TARIFF_RECORD_CHANGED', 'The saved tariff plan has an invalid shape.');
    return record;
  }
  async function allPlans() {
    const names = (await readdir(root)).filter(name => name.endsWith('.json') && UUID.test(name.slice(0, -5))).sort();
    const records = [];
    for (const name of names) records.push(await load(name.slice(0, -5)));
    return records;
  }
  async function selectionHistory() {
