function atomic(value,label) {
  if (typeof value !== 'string' || !/^[1-9][0-9]{0,38}$/.test(value))
    throw fail('QUOTE_ATOMIC_UNITS_REQUIRED',label+' must be a positive integer string of at most 39 digits.');
