}
function microUsd(value,label) {
  if (typeof value !== 'string' || !/^(0|[1-9][0-9]*)(\.[0-9]{1,6})?$/.test(value))
    throw fail('QUOTE_USD_REQUIRED',label+' must be a USD decimal string with at most six places.');
