        const method = action === 'pause' ? 'setPaused' : action;
        return reply(200, await model[method](input));
      } catch (error) {
        if (res.headersSent) { res.destroy(); return; }
        const code = codeOf(error), status = error.status ?? (code === 'SF98_DELIVERY_BUSY' ? 409 : code === 'ENOENT' ? 404 :
          error instanceof TypeError || error instanceof RangeError ? 400 : 500);
        reply(status, { code, message: explanations[code] ?? (status === 500 ?
          'The operation could not complete. Inspect the retained workspace and original journals.' : code.toLowerCase().replaceAll('_', ' ') + '.') });
      }
    })();
    operations.add(task); task.finally(() => operations.delete(task)).catch(() => {});
    return task.then(() => true);
  };
  handler.close = () => { closing = true; for (const req of readers) req.destroy(); };
  handler.done = () => Promise.allSettled([...operations]);
  return handler;
}

export async function startDestinationsServer({ port = 8478, basePath = '', ...options } = {}) {
  if (!Number.isInteger(port) || port < 0 || port > 65535) throw fault('INVALID_PORT');
  const model = await openDestinationWorkspace(options);
  let handler, closePromise;
  const server = createServer((req, res) => {
    if (!handler) { res.writeHead(503); res.end(); return; }
    handler(req, res).then(handled => { if (!handled) { res.writeHead(404); res.end(); } })
      .catch(() => { if (!res.headersSent) res.writeHead(500); res.end(); });
  });
  server.requestTimeout = 30000; server.headersTimeout = 10000; server.keepAliveTimeout = 2000;
  try {
    await new Promise((done, reject) => { server.once('error', reject); server.listen(port, '127.0.0.1', () => { server.off('error', reject); done(); }); });
    const selected = server.address().port, url = new URL('http://127.0.0.1:' + selected).origin;
    handler = await createDestinationsHandler({ model, basePath,
      origins: [url, 'http://localhost:' + selected] });
    return { model, server, url: url + basePath + '/', close() {
      if (closePromise) return closePromise;
      const attempt = (async () => {
        handler.close();
        const stopped = server.listening ? new Promise(done => server.close(done)) : Promise.resolve();
        server.closeIdleConnections?.();
        let modelError;
        try { await model.close(); } catch (error) { modelError = error; }
        await handler.done();
        server.closeAllConnections?.(); await stopped;
        if (modelError) throw modelError;
      })();
      closePromise = attempt;
      attempt.catch(() => { if (closePromise === attempt) closePromise = undefined; });
      return attempt;
    } };
  } catch (error) { server.close(); await model.close(); throw error; }
}

// MIT. Private destination metadata beside the original SF98 journals.
import { constants } from 'node:fs';
import { mkdir, open, lstat, realpath, rename, unlink, readdir } from 'node:fs/promises';
import { isAbsolute, resolve, join, dirname, sep } from 'node:path';
import { createHash, randomUUID } from 'node:crypto';

export const ROOT_SCHEMA = 'stellar-forge.sf98.destinations.v1';
export const DESTINATION_SCHEMA = 'stellar-forge.sf98.destination.v1';
export const CURSOR_SCHEMA = 'stellar-forge.sf98.destination-cursor.v1';
