    'COPY ' + json(['merchant.tgz','archive.mjs','runtime.mjs','runtime-profile.mjs','profile.json','runtime-contract.json',build + '/']),
    'RUN ' + json([p.runtime.node,join(build,'runtime.mjs'),'install',join(build,'runtime-contract.json')]),
    '',
