  need(Array.isArray(readOnlyRoots) && readOnlyRoots.length <= 128, 'readOnlyRoots must list the selected external source roots');
  const roots = readOnlyRoots.map((file, index) => absolute(file, 'readOnlyRoots[' + index + ']'));
