        bytes = Buffer.from(input.base64, 'base64');
        need(bytes.toString('base64') === input.base64 && /^[a-f0-9]{64}$/.test(input.expectedSha256 ?? '') &&
          sha(bytes) === input.expectedSha256, 'REVIEWER_PACKET_CHANGED');
