    need(existing.schema === WORKSPACE_SCHEMA && existing.packetId === receipt.packetId &&
      existing.packetSha256 === receipt.packetSha256 && existing.state === 'READY', 'REVIEWER_RECEIPT_CHANGED');
    receipt = existing;
